{
  "passageId": "personal-identity",
  "items": [
    {
      "id": "R1",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "과거와 현재의 인격이 동일하다는 사실을 근거로 현재의 내가 약속을 지켜야 한다는 판단을 도출한다."
    },
    {
      "id": "R2",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "약속을 지켜야 한다는 판단은 인격의 동일성이 생각의 기반이라는 일반적 설명을 보여 주는 사례이다."
    },
    {
      "id": "R3",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "영혼의 지속을 인정하는 기존 견해와 자기의식으로 영혼의 실재를 보장할 수 없다는 칸트의 견해를 대비한다."
    },
    {
      "id": "R4",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자기의식이 인식의 조건에 불과하다는 점은 그것이 영혼의 실재를 보장하지 않는다는 결론의 근거이다."
    },
    {
      "id": "R5",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "인식의 조건은 실재를 보장하지 않는다는 일반 원리를 자기의식과 영혼의 경우에 적용한다."
    },
    {
      "id": "R6",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "자기의식이 영혼의 실재 가능성은 열어두지만 실제 존재까지 보장하지는 못한다는 한계를 제시한다."
    },
    {
      "id": "R7",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자기의식이 영혼의 실재를 보장하지 못한다는 칸트 자신의 논의가 영혼을 인격으로 보는 추론을 반박하는 근거가 된다."
    },
    {
      "id": "R8",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "두 전제에 쓰인 의식을 실재 함축 여부라는 동일한 기준으로 비교하여 의미의 차이를 드러낸다."
    },
    {
      "id": "R9",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "두 번째 전제가 생각하는 나는 생각한다는 말과 같다는 점으로부터 그 의식이 실재를 함축하지 않는다고 설명한다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "두 전제에서 의식의 의미가 다르다는 사실이 영혼이 인격이라는 결론을 도출할 수 없다는 판단을 뒷받침한다."
    },
    {
      "id": "R11",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "영혼을 인격으로 증명하는 추론의 한계에 대응하여 동일한 인격을 선행적으로 가정하는 대안을 제시한다."
    },
    {
      "id": "R12",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "생각이 시간의 흐름을 따라 구성된다는 점을 근거로 통시적으로 동일한 인격이 필요하다고 설명한다."
    },
    {
      "id": "R13",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "생각의 성립에 통시적으로 동일한 인격이 필요하다는 이유로 동일 인격의 가정이 선행해야 한다는 주장을 정당화한다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "칸트의 논의는 인격의 동일성이 모든 생각의 기반이라는 설명을 생각의 시간적 구성과 가능 조건으로 자세히 풀어 준다."
    },
    {
      "id": "R15",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "스트로슨이 칸트의 동일 인격 가정을 철학적 상상에 불과하다고 명시적으로 문제 삼는다."
    },
    {
      "id": "R16",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "인격에서 신체를 간과한 칸트와 신체를 인격의 구성에 포함한 스트로슨의 견해를 나란히 대비한다."
    },
    {
      "id": "R17",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "신체를 매개로 대상을 경험한다는 과학적 사실이 경험으로 인격의 통시적 동일성을 뒷받침한다는 주장의 근거가 된다."
    },
    {
      "id": "R18",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자아 인식이 경험적 인식에서 추상화된다는 설명을 근거로 경험이 인격의 동일성을 뒷받침한다는 결론을 도출한다."
    },
    {
      "id": "R19",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "스트로슨의 논증 내부에서 자기의식의 경험 의존성이 칸트의 견해가 잘못이라는 판단의 이유로 제시된다."
    },
    {
      "id": "R20",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "스트로슨은 자기의식을 인식의 가능 조건으로 보는 칸트의 주장을 직접 잘못이라고 부정한다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "동일한 자아가 경험적 인식의 성립에 선행해야 한다는 점으로부터 자아 인식이 경험에서 추상화된 것은 아니라는 결론을 도출한다."
    },
    {
      "id": "R22",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "롱게네스는 자아가 경험의 성립에 필요하다는 이유를 들어 스트로슨의 경험적 추상화 설명을 부정한다."
    },
    {
      "id": "R23",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "롱게네스와 칸트는 통시적으로 동일한 자아나 인격을 인식과 생각의 성립에 필요한 것으로 본다는 점에서 견해가 일치한다."
    },
    {
      "id": "R24",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "인간이 도덕적 존재로서 자율성을 지닌다는 설명을 시공간적 경험 속에서 스스로 선택한다는 내용으로 구체화한다."
    },
    {
      "id": "R25",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자율성이 시공간적 경험 속의 선택이라는 의미에서 그러한 선택에 신체가 필요하다는 판단을 이끌어 낸다."
    },
    {
      "id": "R26",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자율성이 살아가는 동안 경험하는 것들 사이의 선택이라는 설명을 근거로 생존이 필요하다는 판단을 도출한다."
    },
    {
      "id": "R27",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자율성의 성립에 살아 있는 신체가 필요하다는 점이 신체를 인격 동일성의 기준으로 삼는 주장을 뒷받침한다."
    },
    {
      "id": "R28",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "스트로슨과 롱게네스는 인격이나 그 동일성을 설명할 때 신체를 중요하게 포함한다는 공통 견해를 보인다."
    },
    {
      "id": "R29",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "신체를 인격 동일성의 기준으로 삼는 롱게네스의 견해와 인격 문제에서 신체를 간과한 칸트의 접근을 대비한다."
    }
  ]
}

